  core('A','Launch','Functions, Domain, Range, and Representations','cover','Unit 2 · Functions',`<div class="fn21-cover"><div><div class="cover-kicker">IB Mathematics: Applications and Interpretation SL</div><div class="fn21-number">2.1</div><h1>Functions, Domain, Range, and Representations</h1><p>Build the language that every later model uses: one output per allowed input, precise notation, valid domains, meaningful ranges and evidence from graphs.</p><div class="fn21-pill-row"><span>SL 2.2</span><span>SL 2.3</span><span>SL 2.4</span><span>Technology</span><span>Modelling</span></div><button class="primary-btn route-jump" data-go="practice">Open Practice Studio</button></div>${coverVisual}</div>`,true);
  core('A','Launch','Inquiry launch · one input, one decision','content','Think before calculating',`<div class="fn21-inquiry"><div><span>STARTING SCENARIO</span><h2>A school transport app receives a distance and returns one quoted fare.</h2><p>What must be true for the fare rule to be a function? Which distances are allowed? What information would a graph reveal that a formula might hide?</p></div><textarea class="student-note tall" data-note="fn21-inquiry" placeholder="Write an initial claim, one condition and one question."></textarea></div>`);
  core('A','Launch','The recommended IB SL route','content','Scope and pacing',`<div class="fn21-route-map"><article><b>2.1A</b><span>Function rule</span></article><article><b>2.1B</b><span>Notation and preimages</span></article><article><b>2.1C</b><span>Domain and range</span></article><article><b>2.1D</b><span>Graph features</span></article><article><b>2.1E</b><span>Technology and modelling</span></article></div><div class="fn21-scope-note"><b>Default:</b> the current IB AI SL core. Orange screens are optional reference-supported extension and can be opened from the header.</div>`);
  core('A','Launch','Learning outcomes','content','By the end',`<div class="fn21-outcomes"><label><input type="checkbox" data-reflect="fn21-o1"><span>Decide whether a relation is a function and justify the decision from any representation.</span></label><label><input type="checkbox" data-reflect="fn21-o2"><span>Use function notation to evaluate images and determine preimages.</span></label><label><input type="checkbox" data-reflect="fn21-o3"><span>Determine mathematical and contextual domains and ranges.</span></label><label><input type="checkbox" data-reflect="fn21-o4"><span>Read key graph features and use technology to find relevant intersections.</span></label><label><input type="checkbox" data-reflect="fn21-o5"><span>Translate among context, table, mapping, formula and graph, then evaluate limitations.</span></label></div>`);
  core('A','Launch','Readiness check','content','Activate prior knowledge',`<div class="fn21-diagnostic"><article><span>1</span><h3>Coordinates</h3><p>Can you read an ordered pair as input then output?</p></article><article><span>2</span><h3>Substitution</h3><p>Can you replace every occurrence of a variable accurately?</p></article><article><span>3</span><h3>Inequalities</h3><p>Can you distinguish included and excluded endpoints?</p></article><article><span>4</span><h3>Technology</h3><p>Can you choose a window that matches the contextual domain?</p></article></div><textarea class="student-note" data-note="fn21-readiness" placeholder="Record the one prerequisite that needs a two-minute review."></textarea>`);
  core('A','Function concept','A relation connects inputs and outputs','content','Core definition',`<div class="fn21-two"><article class="fn21-key"><span>RELATION</span><h2>Any set of ordered pairs connecting two variables.</h2><div class="fn21-math">\[\{(x,y)\}\]</div></article><article class="fn21-key accent"><span>FUNCTION</span><h2>Every allowed input has exactly one output.</h2><div class="fn21-math">\[x\longmapsto f(x)\]</div></article></div><div class="fn21-note"><b>Allowed:</b> different inputs may share an output. <b>Not allowed:</b> one input producing two different outputs.</div>`);
  core('A','Function concept','Mapping diagrams expose the rule','content','Read arrows, not appearances',`<div class="fn21-two"><div>${mapFunction}</div><article class="fn21-key"><span>WHY IT IS A FUNCTION</span><ul><li>Each domain element has one outgoing arrow.</li><li>The output 5 is used twice, which is allowed.</li><li>No input is left without an output.</li></ul><div class="fn21-mini">Domain \(=\{-2,0,3\}\)<br>Range \(=\{1,5\}\)</div></article></div>`);
  core('A','Function concept','Tables and ordered pairs','content','Repeated inputs are the decisive test',`<div class="fn21-table-compare"><article><span>FUNCTION</span><table><tr><th>x</th><th>f(x)</th></tr><tr><td>−1</td><td>4</td></tr><tr><td>2</td><td>4</td></tr><tr><td>5</td><td>9</td></tr></table><p>Repeated output 4 is allowed.</p></article><article class="bad"><span>NOT A FUNCTION</span><table><tr><th>x</th><th>y</th></tr><tr><td>−1</td><td>4</td></tr><tr><td>2</td><td>4</td></tr><tr><td>2</td><td>9</td></tr></table><p>Input 2 has two outputs.</p></article></div>`);
  core('A','Function concept','The vertical-line test','content','A geometric decision',`<div class="fn21-two"><div>${verticalTest}</div><article class="fn21-key"><span>TEST</span><ol><li>Imagine every possible vertical line.</li><li>If each meets the relation at most once, it is a function of \(x\).</li><li>One vertical line with two intersections is enough to reject it.</li></ol></article></div>`);
  worked('A','Function concept','Worked example · decide from ordered pairs','A relation contains \((-3,8),(0,2),(4,8),(0,-1)\). Decide whether it defines \(y\) as a function of \(x\).',[`List the inputs: \(-3,0,4,0\).`,`The input \(0\) is paired with both \(2\) and \(-1\).`,`Therefore one allowed input has two outputs, so the relation is not a function.`],`\[\boxed{\text{Not a function}}\]`);
  student('A','Function concept','Student turn · mapping evidence','A mapping sends \(-2\mapsto 6\), \(1\mapsto 4\), \(5\mapsto 6\). Is it a function? State its domain and range.','fn21-turn-a1','Yes. Every input has one output. Domain \(\{-2,1,5\}\); range \(\{4,6\}\). The repeated output 6 is allowed.');
  clinic('A','Function concept','Repeated outputs do not break a function','“Two arrows end at 6, so the relation is not a function.”','The function rule is checked from each input. Many-to-one is allowed; one-to-many is not.');
  ext('A','Extension','Implicit relations need an output check','content','Reference-supported extension',`<div class="fn21-two"><article class="fn21-key"><span>EXAMPLE 1</span><div class="fn21-math">\[y^2=x\]</div><p>For \(x=9\), both \(y=3\) and \(y=-3\). It is not \(y\) as a function of \(x\).</p></article><article class="fn21-key"><span>EXAMPLE 2</span><div class="fn21-math">\[y=\sqrt{x}\]</div><p>The principal square-root branch chooses one output for each \(x\ge0\), so it is a function.</p></article></div>`);
  ext('A','Extension','A domain restriction can create a function','content','Choose one branch deliberately',`<div class="fn21-extension-task"><h2>The circle \(x^2+y^2=25\) fails the vertical-line test.</h2><p>Restricting to \(y\ge0\) gives the upper semicircle \(y=\sqrt{25-x^2}\), with domain \([-5,5]\). Each input now has one output.</p><div class="fn21-math">\[y=\sqrt{25-x^2},\qquad -5\le x\le5\]</div></div>`);

  core('B','Teaching block','2.1B · Function notation, images and preimages','content','A new question direction',`<div class="fn21-block-open"><b>2.1B</b><h2>Move in both directions</h2><p><strong>Image question:</strong> input known, output required. <strong>Preimage question:</strong> output known, input required.</p><div class="fn21-arrow-strip"><span>input</span><i>apply \(f\)</i><span>output</span><i>solve backwards</i><span>preimage</span></div></div>`,true);
  core('B','Function notation','Function notation names a rule and an output','content','It is not multiplication',`<div class="fn21-two"><article class="fn21-key"><span>RULE</span><div class="fn21-math">\[f(x)=2x^2-3x+1\]</div><p>The letter \(f\) names the function; \(x\) is a placeholder for an allowed input.</p></article><article class="fn21-key accent"><span>VALUE</span><div class="fn21-math">\[f(4)=2(4)^2-3(4)+1=21\]</div><p>\(f(4)\) is the output when the input is 4.</p></article></div>`);
  worked('B','Function notation','Worked example · evaluate accurately','For \(g(t)=3t^2-5t-4\), calculate \(g(-2)\).',[`Substitute \(-2\) into every occurrence of \(t\).`,`Use brackets: \(g(-2)=3(-2)^2-5(-2)-4\).`,`Evaluate: \(12+10-4=18\).`],`\[\boxed{g(-2)=18}\]`);
  student('B','Function notation','Student turn · output with units','A tank contains \(V(t)=480-24t\) litres after \(t\) minutes. Calculate and interpret \(V(7.5)\).','fn21-turn-b1','\(V(7.5)=480-24(7.5)=300\). After 7.5 minutes, the model predicts 300 litres in the tank.');
  core('B','Function notation','Image and preimage','content','Name the direction',`<div class="fn21-image-grid"><article><span>IMAGE</span><div class="fn21-math">\[f(3)=11\]</div><p>11 is the image of 3.</p></article><article><span>PREIMAGE</span><div class="fn21-math">\[f(x)=11\]</div><p>3 is a preimage of 11.</p></article><article><span>MULTIPLE PREIMAGES</span><div class="fn21-math">\[f(-3)=f(3)=9\]</div><p>A function may give one output more than one preimage.</p></article></div>`);
  worked('B','Function notation','Worked example · determine preimages','For \(p(x)=x^2-5\), determine all preimages of 11.',[`Set the output equal to 11: \(x^2-5=11\).`,`Solve \(x^2=16\).`,`Both \(x=4\) and \(x=-4\) belong to the domain.`],`\[\boxed{x=-4\text{ or }x=4}\]`);
  core('B','Function notation','A graph answers both directions','content','Vertical for image · horizontal for preimage',`<div class="fn21-graph-directions"><div class="fn21-axis-card"><b>Find \(f(2)\)</b><span>Start at \(x=2\), move vertically to the graph, then horizontally to the output axis.</span></div><div class="fn21-axis-card"><b>Solve \(f(x)=5\)</b><span>Draw or imagine \(y=5\); every intersection gives a preimage.</span></div><svg viewBox="0 0 620 270" role="img" aria-label="Graph showing an image and two preimages"><rect width="620" height="270" rx="22" fill="#fff"/><line x1="45" y1="215" x2="580" y2="215" stroke="#17324d" stroke-width="3"/><line x1="100" y1="245" x2="100" y2="25" stroke="#17324d" stroke-width="3"/><path d="M55 205C145 165 180 62 270 75C365 89 390 205 550 110" fill="none" stroke="#7a1733" stroke-width="6"/><line x1="45" y1="120" x2="580" y2="120" stroke="#d4a72c" stroke-width="4" stroke-dasharray="9 7"/><line x1="275" y1="215" x2="275" y2="76" stroke="#177e89" stroke-width="4" stroke-dasharray="8 6"/></svg></div>`);
  core('B','Function notation','Read notation from a table','content','Coordinates and notation say the same thing',`<div class="fn21-two"><table class="fn21-table"><tr><th>x</th><th>−2</th><th>0</th><th>3</th><th>7</th></tr><tr><th>f(x)</th><td>5</td><td>−1</td><td>5</td><td>12</td></tr></table><article class="fn21-key"><ul><li>\(f(0)=-1\).</li><li>The image of 7 is 12.</li><li>The preimages of 5 are \(-2\) and 3.</li><li>The point \((3,5)\) lies on the graph.</li></ul></article></div>`);
  core('B','Function notation','Interpret function notation in context','content','State variable, value and units',`<div class="fn21-context-interpret"><div class="fn21-math">\[C(12)=47\]</div><p>Weak: “12 gives 47.”</p><p class="good"><b>Complete:</b> For a 12 km delivery, the model predicts a charge of QAR 47.</p><div class="fn21-note">The input unit and output unit are different; both belong in the sentence.</div></div>`);
  core('B','Function notation','Independent and dependent variables','content','The rule encodes dependence',`<div class="fn21-two"><article class="fn21-key"><span>INDEPENDENT VARIABLE</span><h2>Chosen, controlled or observed input</h2><p>Example: distance \(d\), measured in kilometres.</p></article><article class="fn21-key accent"><span>DEPENDENT VARIABLE</span><h2>Output determined by the rule</h2><p>Example: charge \(C(d)\), measured in QAR.</p></article></div>`);
  core('B','Representations','Equivalent representations must agree','content','One model · four checks',`<div class="fn21-four"><article><b>Context</b><span>QAR 5 fixed plus QAR 2 per km.</span></article><article><b>Formula</b><span>\(C(d)=5+2d\)</span></article><article><b>Table</b><span>\((0,5),(2,9),(5,15)\)</span></article><article><b>Graph</b><span>Line through \((0,5)\) with gradient 2.</span></article></div><div class="fn21-note"><b>Verification:</b> substitute one table input into the formula and check that the graph contains the same point.</div>`);
  core('B','Representations','Interactive representation match','content','Test consistency, not memory',`<div class="fn21-interactive" data-fn21-match><div class="fn21-match-question"><span>MODEL</span><h2>“A service starts at QAR 12 and adds QAR 3 for each item.”</h2></div><div class="fn21-choice-row"><button data-answer="0">\(C(n)=3+12n\)</button><button data-answer="1">\(C(n)=12+3n\)</button><button data-answer="0">\(C(n)=12n\)</button></div><div class="fn21-feedback" aria-live="polite">Choose the representation that preserves both parameter meanings.</div></div>`);
  checkpoint('B','Checkpoint','Can you move forward and backward?',[`Explain the difference between an image and a preimage.`,`Calculate \(h(-3)\) for \(h(x)=4-2x\).`,`Determine every preimage of 9 under \(f(x)=x^2\).`,`Interpret \(T(8)=26\) when \(T\) is minutes and the input is kilometres.`]);
  ext('B','Extension','Determine parameters from function values','content','Reference-supported extension',`<div class="fn21-extension-task"><h2>A linear function satisfies \(f(2)=11\) and \(f(7)=31\).</h2><div class="fn21-math">\[m=\frac{31-11}{7-2}=4,\qquad f(x)=4x+3\]</div><p>Function values are points on the graph. Two distinct points determine a unique linear rule.</p></div>`);
  ext('B','Extension','Composition notation preview','content','Preview only · full treatment in Lesson 2.5',`<div class="fn21-two"><article class="fn21-key"><span>TWO-STAGE PROCESS</span><p>First convert a distance, then calculate a cost.</p><div class="fn21-math">\[(C\circ d)(t)=C(d(t))\]</div></article><article class="fn21-key"><span>SCOPE</span><p>This screen only reads the notation. Constructing and simplifying composite functions belongs to Lesson 2.5.</p></article></div>`);

  core('C','Teaching block','2.1C · Domain and range','content','Inputs allowed · outputs produced',`<div class="fn21-block-open"><b>2.1C</b><h2>A formula does not tell the whole story</h2><p>The <strong>mathematical domain</strong> comes from the rule. A <strong>contextual domain</strong> may be smaller because of time, capacity, counting or physical constraints.</p></div>`,true);
  core('C','Domain and range','Read domain and range from a mapping or table','content','List each value once',`<div class="fn21-two"><div>${mapFunction}</div><article class="fn21-key"><span>MAPPING</span><p>Domain: all inputs that appear.</p><p>Range: all outputs actually reached.</p><div class="fn21-math">\[D=\{-2,0,3\},\qquad R=\{1,5\}\]</div><p>The codomain may contain more possible outputs than the range; the range records what is produced.</p></article></div>`);
  core('C','Domain and range','Set notation and interval notation','content','Choose notation that communicates endpoints',`<div class="fn21-notation-grid"><article><b>Set-builder</b><span>\(\{x\in\mathbb R\mid -2\le x<5\}\)</span></article><article><b>Interval</b><span>\([-2,5)\)</span></article><article><b>Inequality</b><span>\(-2\le x<5\)</span></article><article><b>Words</b><span>All real inputs from −2 inclusive to 5 exclusive.</span></article></div>`);
  core('C','Domain and range','Number lines encode inclusion','content','Closed means included · open means excluded',`<div class="fn21-number-lines"><div><span>\([-3,4]\)</span><svg viewBox="0 0 620 90"><line x1="55" y1="45" x2="565" y2="45" stroke="#17324d" stroke-width="4"/><line x1="160" y1="45" x2="455" y2="45" stroke="#177e89" stroke-width="10"/><circle cx="160" cy="45" r="11" fill="#177e89"/><circle cx="455" cy="45" r="11" fill="#177e89"/><text x="160" y="78" text-anchor="middle">−3</text><text x="455" y="78" text-anchor="middle">4</text></svg></div><div><span>\((-3,4]\)</span><svg viewBox="0 0 620 90"><line x1="55" y1="45" x2="565" y2="45" stroke="#17324d" stroke-width="4"/><line x1="160" y1="45" x2="455" y2="45" stroke="#7a1733" stroke-width="10"/><circle cx="160" cy="45" r="11" fill="#fff" stroke="#7a1733" stroke-width="5"/><circle cx="455" cy="45" r="11" fill="#7a1733"/><text x="160" y="78" text-anchor="middle">−3</text><text x="455" y="78" text-anchor="middle">4</text></svg></div></div>`);
  core('C','Domain and range','Read endpoints directly from a graph','content','Project horizontally and vertically',`<div class="fn21-two"><svg class="fn21-endpoint-graph" viewBox="0 0 620 300" role="img" aria-label="Line segment with an open left endpoint and closed right endpoint"><rect width="620" height="300" rx="22" fill="#fff"/><line x1="55" y1="238" x2="570" y2="238" stroke="#17324d" stroke-width="3"/><line x1="135" y1="270" x2="135" y2="35" stroke="#17324d" stroke-width="3"/><line x1="205" y1="205" x2="500" y2="80" stroke="#7a1733" stroke-width="7"/><circle cx="205" cy="205" r="11" fill="#fff" stroke="#7a1733" stroke-width="5"/><circle cx="500" cy="80" r="11" fill="#7a1733"/><text x="205" y="266" text-anchor="middle">−1</text><text x="500" y="266" text-anchor="middle">5</text><text x="103" y="205" text-anchor="middle">−2</text><text x="103" y="82" text-anchor="middle">4</text></svg><article class="fn21-key"><div class="fn21-math">\[D=(-1,5],\qquad R=(-2,4]\]</div><p>The open point removes both its input and its output here because no other point produces \(y=-2\).</p></article></div>`);
  core('C','Natural domain','Denominators cannot equal zero','content','Locate every excluded input',`<div class="fn21-two"><article class="fn21-key"><span>RULE</span><div class="fn21-math">\[r(x)=\frac{7}{(x-3)(x+2)}\]</div><p>The denominator is zero at \(x=3\) and \(x=-2\).</p></article><article class="fn21-key accent"><span>DOMAIN</span><div class="fn21-math">\[\mathbb R\setminus\{-2,3\}\]</div><p>A calculator may visually connect branches across a narrow gap; the algebraic restriction remains.</p></article></div>`);
  core('C','Natural domain','Even roots require a non-negative radicand','content','Solve an inequality',`<div class="fn21-two"><article class="fn21-key"><span>RULE</span><div class="fn21-math">\[s(x)=\sqrt{12-3x}\]</div><p>Require \(12-3x\ge0\).</p></article><article class="fn21-key accent"><span>DOMAIN</span><div class="fn21-math">\[x\le4\]</div><p>The principal square root produces only non-negative outputs.</p></article></div>`);
  core('C','Contextual domain','Time and capacity restrict valid inputs','content','Context can narrow a natural domain',`<div class="fn21-context-grid"><article><span>MATHEMATICAL</span><div class="fn21-math">\[H(t)=2.4t+1\]</div><p>Defined for every real \(t\).</p></article><article><span>CONTEXTUAL</span><div class="fn21-math">\[0\le t\le18\]</div><p>The experiment starts at 0 minutes and ends at 18 minutes.</p></article><article><span>OUTPUT LIMIT</span><div class="fn21-math">\[1\le H\le44.2\]</div><p>The range follows from the restricted domain.</p></article></div>`);
  core('C','Contextual domain','Discrete domains are not intervals of real numbers','content','Counts use whole numbers',`<div class="fn21-two"><article class="fn21-key"><span>CONTINUOUS</span><p>Elapsed time, mass and distance can usually vary through real values.</p><div class="fn21-math">\[0\le t\le12\]</div></article><article class="fn21-key accent"><span>DISCRETE</span><p>Students, buses and completed payments are counted.</p><div class="fn21-math">\[n\in\{0,1,2,\ldots,40\}\]</div></article></div>`);
  core('C','Range','Range from a finite representation','content','Remove repeats but preserve values',`<div class="fn21-two"><table class="fn21-table"><tr><th>x</th><th>0</th><th>1</th><th>2</th><th>3</th><th>4</th></tr><tr><th>f(x)</th><td>6</td><td>9</td><td>9</td><td>14</td><td>20</td></tr></table><article class="fn21-key"><span>RANGE</span><div class="fn21-math">\[\{6,9,14,20\}\]</div><p>Sets do not list 9 twice.</p></article></div>`);
  core('C','Range','Range of a monotonic rule on a closed interval','content','Endpoint outputs are enough',`<div class="fn21-two"><article class="fn21-key"><span>MODEL</span><div class="fn21-math">\[f(x)=-3x+10,\quad 0\le x\le4\]</div><p>The rule decreases throughout the interval.</p></article><article class="fn21-key accent"><span>ENDPOINTS</span><div class="fn21-math">\[f(0)=10,\qquad f(4)=-2\]</div><div class="fn21-math">\[R=[-2,10]\]</div></article></div>`);
  core('C','Range','Turning points can control the range','content','Check interior extrema and endpoints',`<div class="fn21-two"><article class="fn21-key"><span>MODEL</span><div class="fn21-math">\[y=(x-2)^2-3,\quad -1\le x\le5\]</div><p>The vertex gives the minimum \(-3\) at \(x=2\).</p></article><article class="fn21-key accent"><span>MAXIMUM</span><p>Endpoint outputs are 6 and 6.</p><div class="fn21-math">\[R=[-3,6]\]</div></article></div>`);
  core('C','Range','An open endpoint may remove a bound','content','Approached does not mean attained',`<div class="fn21-two"><article class="fn21-key"><span>MODEL</span><div class="fn21-math">\[f(x)=3x+2,\quad -1\le x<4\]</div></article><article class="fn21-key accent"><span>RANGE</span><p>\(f(-1)=-1\) is included. As \(x\to4^-\), \(f(x)\to14\), but 14 is not attained.</p><div class="fn21-math">\[R=[-1,14)\]</div></article></div>`);
  worked('C','Domain and range','Worked example · mathematical and contextual restrictions','A lift height is modelled by \(h(t)=1.5+3.2t\) metres for a journey lasting 6 seconds. State the contextual domain and range.',[`Time begins at \(t=0\) and ends at \(t=6\), so \(D=[0,6]\).`,`The function increases, so evaluate the endpoints.`,`\(h(0)=1.5\) and \(h(6)=20.7\).`],`\[D=[0,6],\qquad R=[1.5,20.7]\text{ m}\]`);
  student('C','Domain and range','Student turn · formula plus context','The model \(B(t)=18+7.5t\) gives battery percentage for \(0\le t\le8\). State the mathematical output interval, then explain the physical range that may require a smaller domain.','fn21-turn-c1','The formula gives outputs from 18% to 78%. A battery percentage must remain between 0% and 100%; beyond the stated domain the linear rule should not be assumed to continue.');
  clinic('C','Domain and range','A viewing window is not a domain','“My calculator window is \(-10\le x\le10\), so that is the domain.”','A window displays part of a graph. The domain comes from the rule and the context, and may extend far outside the screen.');
  core('C','Domain and range','Domain-and-range decision checklist','checkpoint','Use the shortest valid method',`<div class="fn21-decision-tree"><div><b>1</b><span>What representation is given?</span></div><i>→</i><div><b>2</b><span>What inputs are defined and meaningful?</span></div><i>→</i><div><b>3</b><span>Which outputs are actually produced?</span></div><i>→</i><div><b>4</b><span>Are bounds included, excluded or discrete?</span></div></div>`);
  ext('C','Extension','Combined radical and denominator restrictions','content','Reference-supported extension',`<div class="fn21-extension-task"><h2>Determine the domain of \(f(x)=\dfrac{\sqrt{2x+8}}{x^2-9}\).</h2><p>Require \(x\ge-4\), then exclude \(x=-3\) and \(x=3\).</p><div class="fn21-math">\[[-4,-3)\cup(-3,3)\cup(3,\infty)\]</div></div>`);
  ext('C','Extension','Range of a translated reciprocal','content','Reference-supported extension',`<div class="fn21-extension-task"><div class="fn21-math">\[g(x)=\frac{1}{x-2}+4\]</div><p>The reciprocal term can be any non-zero real number, so the output can never equal 4.</p><div class="fn21-math">\[R=(-\infty,4)\cup(4,\infty)\]</div></div>`);
  ext('C','Extension','Model domain versus mathematical domain','content','A modelling judgment',`<div class="fn21-two"><article class="fn21-key"><span>FORMULA</span><p>\(T(d)=12+1.4d\) is algebraically defined for every real \(d\).</p></article><article class="fn21-key"><span>VALIDATED MODEL</span><p>Data were collected only for \(0\le d\le60\). Using \(T(400)\) is extreme extrapolation, even though the calculator returns a number.</p></article></div>`);

  core('D','Teaching block','2.1D · Reading features of graphs','content','Read before calculating',`<div class="fn21-block-open"><b>2.1D</b><h2>A graph is a compressed mathematical argument</h2><p>It can show zeros, extrema, sign, direction of change, endpoints, gaps and multiple solutions at once—provided the axes and window are trustworthy.</p></div>`,true);
  core('D','Graph features','Intercepts and zeros','content','Coordinates matter',`<div class="fn21-three"><article><span>X-INTERCEPT</span><div class="fn21-math">\[f(x)=0\]</div><p>Point \((a,0)\); zero/root \(x=a\).</p></article><article><span>Y-INTERCEPT</span><div class="fn21-math">\[f(0)\]</div><p>Point \((0,f(0))\).</p></article><article><span>CONTEXT</span><p>An intercept may represent break-even, an initial amount or a threshold—only if it lies in the contextual domain.</p></article></div>`);
  core('D','Graph features','Local and global extrema','content','State the point and its status',`<div class="fn21-two"><div>${graphFeatures}</div><article class="fn21-key"><ul><li>A <b>local maximum</b> exceeds nearby values.</li><li>A <b>global maximum</b> is the greatest output on the whole domain.</li><li>An included endpoint can be a global extremum.</li><li>Use coordinates and units when available.</li></ul></article></div>`);
  core('D','Graph behaviour','Increasing and decreasing intervals','content','Follow the output as input moves right',`<div class="fn21-behaviour"><div class="up"><b>INCREASING</b><span>As \(x\) increases, \(f(x)\) increases.</span></div><div class="down"><b>DECREASING</b><span>As \(x\) increases, \(f(x)\) decreases.</span></div><div class="flat"><b>CONSTANT</b><span>The output remains unchanged over an interval.</span></div></div><div class="fn21-note">Intervals describe input values, not output values.</div>`);
  core('D','Graph behaviour','Positive and negative intervals','content','Position relative to the x-axis',`<div class="fn21-two"><article class="fn21-key"><span>POSITIVE</span><div class="fn21-math">\[f(x)>0\]</div><p>The graph lies above the \(x\)-axis.</p></article><article class="fn21-key accent"><span>NEGATIVE</span><div class="fn21-math">\[f(x)<0\]</div><p>The graph lies below the \(x\)-axis.</p></article></div>`);
  clinic('D','Graph behaviour','Positive is not the same as increasing','“The graph is above the x-axis, so it is increasing.”','Positive/negative describes the output sign. Increasing/decreasing describes how outputs change as inputs move right. A positive graph can decrease.');
  core('D','Graph features','Endpoints, holes and jumps','content','Inclusion changes conclusions',`<div class="fn21-symbol-grid"><article><span class="closed-dot"></span><b>Closed point</b><p>Included in the relation.</p></article><article><span class="open-dot"></span><b>Open point</b><p>Excluded at that coordinate.</p></article><article><span class="jump-icon">↕</span><b>Jump</b><p>Left and right pieces approach different outputs.</p></article><article><span class="hole-icon">○</span><b>Hole</b><p>A missing point may remove an input or output.</p></article></div>`);
  core('D','Graph features','Feature-reading protocol','content','A repeatable order',`<div class="fn21-feature-protocol"><div><b>1</b><span>Axes, scales, units</span></div><div><b>2</b><span>Domain and range</span></div><div><b>3</b><span>Intercepts and endpoints</span></div><div><b>4</b><span>Extrema and direction</span></div><div><b>5</b><span>Sign and discontinuities</span></div><div><b>6</b><span>Contextual interpretation</span></div></div>`);
  worked('D','Graph features','Worked example · extract a complete feature set','A graph has domain \([-4,6]\), x-intercepts at \(-2\) and 5, a global maximum \((1,8)\), and a global minimum \((6,-3)\). State its range and the intervals on which its output can be positive.',[`The global output bounds give the range \([-3,8]\).`,`Zeros divide the domain into sign intervals.`,`Use the displayed graph to test one point in each interval; intercept data alone do not determine the sign pattern.`],`\[R=[-3,8]\]`,`<p class="fn21-caution"><b>Important:</b> A sign conclusion requires the graph or another representation, not only a list of zeros.</p>`);
  student('D','Graph features','Student turn · analyse the labelled graph','Use the displayed feature graph to identify the open and closed domain endpoints, the number of x-intercepts, and one interval where the function is decreasing.','fn21-turn-d1',`The left endpoint is open and the right endpoint closed. The graph has three x-intercepts. One decreasing interval runs from the local maximum to the local minimum; exact interval notation depends on the labelled x-scale.`);
  core('D','Technology','Trace finds coordinates, intersect solves equations','content','Record evidence, not button presses',`<div class="fn21-gdc-grid"><article><b>TRACE</b><p>Estimate \(f(a)\), intercepts or extrema from the graph.</p></article><article><b>INTERSECT</b><p>Solve \(f(x)=g(x)\) by graphing both functions.</p></article><article><b>TABLE</b><p>Check values and identify sign changes or a suitable interval.</p></article><article><b>WINDOW</b><p>Match the domain and output scale before trusting “no solution”.</p></article></div>`);
  core('D','Technology','Interactive feature trace','content','Move the input · read the output',`<div class="fn21-interactive" data-fn21-trace><div class="fn21-trace-grid"><div><label>Input \(x\)<input type="range" min="-4" max="6" step="0.1" value="1" data-trace-x></label><div class="fn21-trace-readout" data-trace-output>Move the slider.</div><p>Model: \(f(x)=0.12(x+2)(x-1)(x-5)\).</p></div><svg viewBox="0 0 620 300" data-trace-svg role="img" aria-label="Interactive cubic graph"><rect width="620" height="300" rx="22" fill="#fff"/><line x1="45" y1="215" x2="585" y2="215" stroke="#17324d" stroke-width="3"/><line x1="255" y1="270" x2="255" y2="25" stroke="#17324d" stroke-width="3"/><path data-trace-path fill="none" stroke="#7a1733" stroke-width="6"/><line data-trace-line x1="0" y1="25" x2="0" y2="270" stroke="#d4a72c" stroke-width="4" stroke-dasharray="9 7"/><circle data-trace-point cx="0" cy="0" r="9" fill="#177e89"/></svg></div></div>`);
  core('D','Graph features','A horizontal line may give several preimages','content','All relevant intersections count',`<div class="fn21-two"><article class="fn21-key"><div class="fn21-math">\[f(x)=4\]</div><p>Graph \(y=f(x)\) and \(y=4\). A non-monotonic graph may meet this horizontal line more than once.</p></article><article class="fn21-key accent"><span>REPORTING</span><p>State every solution in the requested domain, with precision justified by the graph or technology.</p></article></div>`);
  checkpoint('D','Checkpoint','Can you read a graph without guessing?',[`Distinguish an x-intercept from a zero.`,`Distinguish positive from increasing.`,`Explain how an open endpoint affects domain or range.`,`Describe what a horizontal intersection represents.`,`State why a graphing window is part of the mathematical evidence.`]);
  ext('D','Extension','Step and tariff graphs','content','Reference-supported extension',`<div class="fn21-two"><article class="fn21-key"><span>STEP MODEL</span><p>A parking charge may stay constant over each completed-hour interval and jump at the next hour.</p><div class="fn21-math">\[C(t)=6\lceil t\rceil\]</div></article><article class="fn21-key"><span>ENDPOINT DECISION</span><p>Open and closed dots show which interval owns a boundary. Two different included outputs at one input would violate the function rule.</p></article></div>`);
  ext('D','Extension','Choose a parameter for continuity','content','Reference-supported extension',`<div class="fn21-extension-task"><h2>Let \(f(x)=ax+3\) for \(x<2\), and \(f(x)=x^2-1\) for \(x\ge2\).</h2><p>The right-hand value at 2 is 3. Matching the left rule gives \(2a+3=3\), so \(a=0\).</p><div class="fn21-math">\[\boxed{a=0}\]</div></div>`);

  core('E','Teaching block','2.1E · Technology, inverse reflection and modelling','content','Use evidence to make a decision',`<div class="fn21-block-open"><b>2.1E</b><h2>Technology supports the model; it does not define it</h2><p>State the domain, enter the rule, choose a revealing window, record the output, verify the result and interpret it.</p></div>`,true);
  core('E','Technology','A transparent GDC workflow','content','Five moves',`<div class="fn21-workflow"><div><b>1</b><span>Define variables and domain.</span></div><div><b>2</b><span>Enter the rule accurately.</span></div><div><b>3</b><span>Choose table or window.</span></div><div><b>4</b><span>Trace, solve or intersect.</span></div><div><b>5</b><span>Verify, round and interpret.</span></div></div>`);
  core('E','Technology','Interactive domain-and-range laboratory','lab','Predict first · calculate second',`<div class="lab fn21-lab"><h2>Linear model on a restricted domain</h2><p>Change the endpoints, gradient and intercept. Predict whether the output increases or decreases before calculating.</p><div id="lesson-lab" data-lab="2.1"></div></div>`);
  core('E','Representations','The rule of four is a validation system','content','Context · table · graph · formula',`<div class="fn21-four large"><article><b>Context</b><span>Meaning, units, assumptions and restrictions.</span></article><article><b>Table</b><span>Exact sampled values and discrete evidence.</span></article><article><b>Graph</b><span>Shape, features and multiple solutions.</span></article><article><b>Formula</b><span>Calculation, algebra and parameter structure.</span></article></div><div class="fn21-note">A disagreement among representations is a warning: the entry, scale, table, formula or interpretation may be wrong.</div>`);
  core('E','Modelling','Delivery-fee inquiry · build the model contract','content','One output is not enough',`<div class="fn21-case"><div><span>SCENARIO</span><h2>A delivery service quotes a fee from distance \(d\), for \(0\le d\le30\) km.</h2><p>A complete model must state the rule, the allowed distance domain, the fee range, the units, boundary ownership and assumptions such as no tolls or surge pricing.</p></div><div class="fn21-case-prompts"><label><b>Representation</b><textarea class="student-note" data-note="fn21-case-rep" placeholder="Formula, table or graph"></textarea></label><label><b>Evaluation</b><textarea class="student-note" data-note="fn21-case-eval" placeholder="One assumption and one limitation"></textarea></label></div></div>`);
  core('E','Inverse relation','Inverse relations swap coordinates','content','Reflection in y=x',`<div class="fn21-two"><div>${inverseVisual}</div><article class="fn21-key"><span>POINT MAPPING</span><div class="fn21-math">\[(x,y)\longmapsto(y,x)\]</div><p>The domain of the original relation becomes the range of the inverse relation, and vice versa.</p><div class="fn21-note">This is the current SL reflection idea. Full algebraic construction is developed in Lesson 2.5.</div></article></div>`);
  core('E','Inverse relation','Interactive inverse-point reflection','content','Swap input and output',`<div class="fn21-interactive" data-fn21-inverse><div class="fn21-inverse-control"><label>Choose \(x\)<input type="range" min="-3" max="5" step="1" value="2" data-inverse-x></label><p>Original rule: \(f(x)=2x+1\).</p><div class="fn21-trace-readout" data-inverse-readout></div></div><svg viewBox="0 0 560 330" data-inverse-svg role="img" aria-label="Point and reflected inverse point"><rect width="560" height="330" rx="22" fill="#fff"/><line x1="40" y1="275" x2="530" y2="275" stroke="#17324d" stroke-width="3"/><line x1="145" y1="310" x2="145" y2="25" stroke="#17324d" stroke-width="3"/><line data-inverse-line x1="80" y1="330" x2="380" y2="30" stroke="#d4a72c" stroke-width="4" stroke-dasharray="10 8"/><circle data-original-point r="10" fill="#7a1733"/><circle data-inverse-point r="10" fill="#177e89"/></svg></div>`);
